insert into public.site_pages(page_key,eyebrow,title,description,sections,eyebrow_en,title_en,description_en,sections_en,hero_image_url,cta_label,cta_label_en,cta_url,secondary_cta_label,secondary_cta_label_en,secondary_cta_url) values
('a-propos','Qui sommes-nous ?','La science au service de vies plus saines','NutVitaGlobalis est née d’une conviction : une information claire, adaptée et humaine peut transformer durablement la santé.','[{"title":"Mission","text":"Rendre l’expertise nutritionnelle fiable et accessible aux familles, aux communautés et aux professionnels pour améliorer la santé et le bien-être de tous."},{"title":"Vision","text":"Un monde où chacun dispose des connaissances nécessaires pour faire de la nutrition un levier de santé et de développement durable."},{"title":"Valeurs","text":"Ces valeurs guident chacune de nos actions au quotidien.","items":["Rigueur scientifique","Proximité et écoute","Respect des cultures","Prévention et impact durable"]},{"title":"Expertise","text":"Une expertise multidisciplinaire pour des solutions adaptées, innovantes et centrées sur l’humain.","items":["Nutrition clinique","Santé publique","Sécurité alimentaire","Formation & accompagnement","Comportement & bien-être"]},{"title":"Notre engagement","text":"Nous nous engageons chaque jour à fournir des solutions fiables, innovantes et accessibles pour transformer la santé et améliorer la qualité de vie.","items":["Approche fondée sur des preuves","Solutions accessibles et inclusives","Impact réel dans les communautés","Partenariats locaux et internationaux"]}]','Who are we?','Science serving healthier lives','NutVitaGlobalis was founded on one conviction: clear, relevant and human guidance can sustainably transform health.','[{"title":"Mission","text":"Make reliable nutrition expertise accessible to families, communities and professionals to improve health and wellbeing for all."},{"title":"Vision","text":"A world where everyone has the knowledge needed to make nutrition a driver of health and sustainable development."},{"title":"Values","text":"These values guide our daily actions.","items":["Scientific rigor","Proximity and listening","Respect for cultures","Prevention and lasting impact"]},{"title":"Expertise","text":"Multidisciplinary expertise for tailored, innovative and people-centered solutions.","items":["Clinical nutrition","Public health","Food security","Training & support","Behavior & wellbeing"]},{"title":"Our commitment","text":"Every day, we commit to reliable, innovative and accessible solutions that transform health and improve lives.","items":["Evidence-based approach","Accessible and inclusive solutions","Real impact in communities","Local and international partnerships"]}]','/images/about-family-hero-v1.png',null,null,null,null,null,null),
('programme-grossesse','Bien nourrir la maman, bien grandir demain.','Nutrition et alimentation pendant la grossesse','Un accompagnement nutritionnel personnalisé à chaque étape de la grossesse pour une mère en bonne santé et un bébé qui se développe harmonieusement.','[{"title":"Accompagnement","items":["Évaluation de l’état nutritionnel","Plans alimentaires personnalisés","Suivi du gain pondéral","Conseils pratiques et recettes saines","Suivi des carences et suppléments","Suivi évolutif et rappels"]},{"title":"Bénéfices","items":["Conseils validés","Suivi sécurisé","Confidentialité assurée","Favorise une récupération post-partum optimale"]},{"title":"Garanties","items":["Approche fondée sur les preuves","Suivi personnalisé","Données sécurisées","Experts en nutrition"]}]','Nourish the mother today, help the child thrive tomorrow.','Nutrition and healthy eating during pregnancy','Personalized nutrition support at every stage of pregnancy for a healthy mother and a thriving baby.','[{"title":"Support","items":["Nutrition status assessment","Personalized meal plans","Weight-gain monitoring","Practical advice and healthy recipes","Deficiency and supplement monitoring","Ongoing follow-up and reminders"]},{"title":"Benefits","items":["Validated guidance","Secure monitoring","Confidential care","Supports optimal postpartum recovery"]},{"title":"Standards","items":["Evidence-based approach","Personalized follow-up","Secure data","Nutrition experts"]}]',null,'Commencer maintenant','Start now','/rendez-vous?programme=grossesse','En savoir plus','Learn more','#benefices'),
('programme-nutrition-infantile','Bien nourrir aujourd’hui pour un avenir meilleur.','Nutrition infantile','Des repères adaptés à chaque âge pour soutenir la croissance, le développement et le bien-être de votre enfant.','[{"title":"Accompagnement","items":["Suivi de la croissance (poids, taille, IMC)","Plans alimentaires adaptés à l’âge","Suivi des apports et des carences","Diversification alimentaire guidée","Rappels de vaccination et suppléments","Conseils pratiques pour les parents"]},{"title":"Bénéfices","items":["Croissance et développement optimaux","Renforce l’immunité","Prévention des carences et maladies","De bonnes habitudes alimentaires durables"]},{"title":"Garanties","items":["Basé sur les courbes de croissance OMS","Suivi personnalisé","Données sécurisées","Experts en nutrition"]}]','Nourish well today for a healthier future.','Infant nutrition','Age-appropriate guidance to support your child’s growth, development and wellbeing.','[{"title":"Support","items":["Growth monitoring (weight, height, BMI)","Age-appropriate meal plans","Intake and deficiency monitoring","Guided food diversification","Vaccination and supplement reminders","Practical guidance for parents"]},{"title":"Benefits","items":["Optimal growth and development","Stronger immunity","Prevention of deficiencies and disease","Lasting healthy eating habits"]},{"title":"Standards","items":["Based on WHO growth standards","Personalized follow-up","Secure data","Nutrition experts"]}]',null,'Commencer maintenant','Start now','/rendez-vous?programme=nutrition-infantile','En savoir plus','Learn more','#benefices'),
('programme-cardiometabolique','Agir aujourd’hui pour votre santé de demain.','Diabète, Hypertension, Dyslipidémie / Syndrome métabolique','Une stratégie alimentaire et un suivi personnalisé pour mieux contrôler vos paramètres, réduire les risques et améliorer votre qualité de vie.','[{"title":"Accompagnement","items":["Évaluation complète et suivi des paramètres","Plans alimentaires thérapeutiques personnalisés","Suivi de la glycémie, tension et lipides","Conseils d’activité physique adaptés","Éducation et coaching personnalisé","Rappels de suivi et traitements"]},{"title":"Bénéfices","items":["Meilleur contrôle des paramètres","Réduction des risques de complications","Amélioration de l’énergie et du bien-être","Accompagnement durable et personnalisé"]},{"title":"Garanties","items":["Approche fondée sur les preuves","Suivi personnalisé","Données sécurisées","Experts en nutrition"]}]','Act today for tomorrow’s health.','Diabetes, Hypertension, Dyslipidemia / Metabolic Syndrome','A nutrition strategy and personalized follow-up to better control your indicators, reduce risks and improve quality of life.','[{"title":"Support","items":["Comprehensive assessment and monitoring","Personalized therapeutic meal plans","Glucose, blood pressure and lipid monitoring","Tailored physical activity guidance","Personalized education and coaching","Follow-up and treatment reminders"]},{"title":"Benefits","items":["Better indicator control","Reduced complication risks","Improved energy and wellbeing","Sustainable personalized support"]},{"title":"Standards","items":["Evidence-based approach","Personalized follow-up","Secure data","Nutrition experts"]}]',null,'Commencer maintenant','Start now','/rendez-vous?programme=cardiometabolique','En savoir plus','Learn more','#benefices'),
('programme-gestion-poids','Atteignez votre équilibre. Durablement.','Gestion du poids','Un parcours réaliste et progressif pour retrouver un poids santé, améliorer vos habitudes et préserver votre bien-être.','[{"title":"Accompagnement","items":["Évaluation et analyse de la composition corporelle","Plans alimentaires équilibrés et personnalisés","Suivi des progrès et ajustements","Conseils d’activité physique adaptés","Coaching motivationnel et comportemental","Suivi des indicateurs clés"]},{"title":"Bénéfices","items":["Perte de poids progressive et durable","Amélioration de la santé métabolique","Plus d’énergie au quotidien","Meilleure confiance en soi"]},{"title":"Garanties","items":["Approche fondée sur les preuves","Suivi personnalisé","Équipe pluridisciplinaire","Résultats durables"]}]','Reach your balance. Sustainably.','Weight management','A realistic, progressive pathway to a healthy weight, improved habits and lasting wellbeing.','[{"title":"Support","items":["Body composition assessment and analysis","Balanced personalized meal plans","Progress monitoring and adjustments","Tailored physical activity guidance","Motivational and behavioral coaching","Key indicator monitoring"]},{"title":"Benefits","items":["Progressive lasting weight management","Improved metabolic health","More daily energy","Greater self-confidence"]},{"title":"Standards","items":["Evidence-based approach","Personalized follow-up","Multidisciplinary team","Lasting results"]}]',null,'Commencer maintenant','Start now','/rendez-vous?programme=gestion-poids','En savoir plus','Learn more','#benefices'),
('programme-nutrition-sportive','Optimisez vos performances. Atteignez vos objectifs.','Nutrition sportive','Des stratégies nutritionnelles adaptées à votre discipline, votre niveau et vos objectifs pour améliorer vos performances, récupérer plus vite et prévenir les blessures.','[{"title":"Accompagnement","items":["Évaluation des besoins nutritionnels","Plans alimentaires adaptés à l’entraînement","Optimisation de l’hydratation et suppléments","Suivi de la composition corporelle","Stratégies de récupération","Conseils pratiques et recettes sportives"]},{"title":"Bénéfices","items":["Amélioration des performances","Récupération plus rapide","Prévention des blessures","Composition corporelle optimale"]},{"title":"Garanties","items":["Experts en nutrition sportive","Plans personnalisés","Suivi régulier","Objectifs mesurables"]}]','Optimize performance. Reach your goals.','Sports nutrition','Nutrition strategies tailored to your sport, level and goals to improve performance, speed recovery and prevent injury.','[{"title":"Support","items":["Nutrition needs assessment","Training-specific meal plans","Hydration and supplement optimization","Body composition monitoring","Recovery strategies","Practical advice and sports recipes"]},{"title":"Benefits","items":["Improved performance","Faster recovery","Injury prevention","Optimal body composition"]},{"title":"Standards","items":["Sports nutrition experts","Personalized plans","Regular follow-up","Measurable goals"]}]','/images/program-sports-hero-v1.png','Commencer maintenant','Start now','/rendez-vous?programme=nutrition-sportive','En savoir plus','Learn more','#benefices')
